// Parse and validate the AI response against the semantic analysis schema
const rawText = $input.first().json.raw_response_text;

const result = {
  validation_status: 'MALFORMED',
  reason_code: 'A-002',
  analysis_json: null,
  is_valid_json: 'false',
  has_summary: 'false',
  has_required_fields: 'false',
  service_fit_valid: 'false',
  intent_signal_valid: 'false',
  urgency_signal_valid: 'false',
  budget_signal_valid: 'false',
  confidence_valid: 'false',
  risk_flags_valid: 'false',
  decision_facts_valid: 'false'
};

try {
  const parsed = JSON.parse(rawText);
  result.analysis_json = JSON.stringify(parsed);
  result.is_valid_json = 'true';

  const requiredFields = ['summary', 'detected_need', 'service_fit', 'intent_signal', 'urgency_signal', 'budget_signal', 'decision_relevant_facts', 'missing_information', 'risk_flags', 'confidence'];
  result.has_required_fields = requiredFields.every(f => parsed[f] !== undefined) ? 'true' : 'false';
  result.has_summary = parsed.summary !== undefined ? 'true' : 'false';

  const validServiceFit = ['IN_SCOPE', 'PARTIAL', 'OUT_OF_SCOPE', 'UNKNOWN'];
  result.service_fit_valid = validServiceFit.includes(parsed.service_fit) ? 'true' : 'false';

  const validSignals = ['HIGH', 'MEDIUM', 'LOW', 'UNKNOWN'];
  result.intent_signal_valid = validSignals.includes(parsed.intent_signal) ? 'true' : 'false';
  result.urgency_signal_valid = validSignals.includes(parsed.urgency_signal) ? 'true' : 'false';

  const validBudget = ['EXPLICIT_FIT', 'EXPLICIT_MISMATCH', 'NOT_PROVIDED', 'AMBIGUOUS'];
  result.budget_signal_valid = validBudget.includes(parsed.budget_signal) ? 'true' : 'false';

  result.confidence_valid = validSignals.includes(parsed.confidence) ? 'true' : 'false';

  const validRiskFlags = ['PROMPT_INJECTION_SUSPECTED', 'ADVERSARIAL_CONTENT', 'CONTRADICTORY_SIGNALS', 'MISSING_CRITICAL_INFO', 'UNUSUAL_REQUEST'];
  result.risk_flags_valid = Array.isArray(parsed.risk_flags) && parsed.risk_flags.every(f => validRiskFlags.includes(f)) ? 'true' : 'false';

  result.decision_facts_valid = Array.isArray(parsed.decision_relevant_facts) && parsed.decision_relevant_facts.every(f => f.fact !== undefined && f.source !== undefined) ? 'true' : 'false';

  const missingInfoValid = Array.isArray(parsed.missing_information);

  if (result.has_required_fields === 'true' &&
      result.service_fit_valid === 'true' &&
      result.intent_signal_valid === 'true' &&
      result.urgency_signal_valid === 'true' &&
      result.budget_signal_valid === 'true' &&
      result.confidence_valid === 'true' &&
      result.risk_flags_valid === 'true' &&
      result.decision_facts_valid === 'true' &&
      missingInfoValid) {
    result.validation_status = 'VALID';
    result.reason_code = 'A-001';
  }
} catch (e) {
  // Keep defaults: MALFORMED, A-002
}

return [{ json: result }];
